import os
import requests


def profile_claims(payload, config=None):
    config = config or {}
    access_token = payload.get("access_token")
    if not access_token:
        raise ValueError("payload must include access_token")

    userinfo_url = config.get("userinfo_url") or os.getenv("AUTH0_USERINFO_URL")
    if not userinfo_url:
        raise ValueError("userinfo_url must be provided in config or AUTH0_USERINFO_URL must be set")

    headers = {
        "Authorization": f"Bearer {access_token}",
        "Accept": "application/json",
    }

    response = requests.get(userinfo_url, headers=headers, timeout=config.get("timeout", 10))
    response.raise_for_status()
    result = response.json()
    return result
